/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'fs';

// Regex for valid identifiers (names, route prefixes, event keys)
const VALID_IDENTIFIER = /^[A-Za-z0-9_./:\-]+$/;

function isValidIdentifier(str) {
  return VALID_IDENTIFIER.test(str);
}

function isValidInteger(str, minValue = 0) {
  if (!/^\d+$/.test(str)) return false;
  const num = parseInt(str, 10);
  if (str !== num.toString()) return false; // No leading zeros
  return num >= minValue;
}

class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity;
    this.refill = refill;
    this.per = per;
    this.state = new Map(); // key -> {tokens: number, lastTick: number}
  }

  advance(key, tick) {
    if (!this.state.has(key)) {
      this.state.set(key, { tokens: this.capacity, lastTick: tick });
    } else {
      const state = this.state.get(key);
      const ticksPassed = tick - state.lastTick;
      const tokensAdded = (this.refill * ticksPassed) / this.per;
      state.tokens = Math.min(this.capacity, state.tokens + tokensAdded);
      state.lastTick = tick;
    }
  }

  allow(key) {
    return this.state.get(key).tokens >= 1;
  }

  record(key, tick) {
    this.state.get(key).tokens -= 1;
  }
}

class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit;
    this.span = span;
    this.state = new Map(); // key -> {ticks: []}
  }

  advance(key, tick) {
    if (!this.state.has(key)) {
      this.state.set(key, { ticks: [] });
    }
    const state = this.state.get(key);
    // Remove ticks that are too old
    const cutoff = tick - this.span;
    state.ticks = state.ticks.filter(t => t > cutoff);
  }

  allow(key) {
    const state = this.state.get(key);
    return state.ticks.length < this.limit;
  }

  record(key, tick) {
    this.state.get(key).ticks.push(tick);
  }
}

function main() {
  const args = process.argv.slice(2);

  if (args.length !== 1 || !['replay', 'summary'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js replay|summary\n');
    process.exit(2);
  }

  const mode = args[0];

  // Read stdin
  const input = readFileSync(0, 'utf8');

  // Parse input
  const lines = input.split('\n');
  const events = [];
  const policies = new Map(); // name -> {type: 'bucket'|'window', instance}
  const routes = new Map(); // prefix -> [policyNames...]
  let firstEventLine = -1;
  let lastTick = -1;

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    let line = lines[lineNum].trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) continue;

    const tokens = line.split(/\s+/);
    const directive = tokens[0];

    if (directive === 'bucket') {
      if (firstEventLine !== -1) {
        process.stderr.write(`error: line ${lineNum + 1}: declarations must come before the first event\n`);
        process.exit(2);
      }

      if (tokens.length !== 5) {
        process.stderr.write(`error: line ${lineNum + 1}: expected bucket <name> <capacity> <refill> <per>\n`);
        process.exit(2);
      }

      const [, name, capacityStr, refillStr, perStr] = tokens;

      if (!isValidIdentifier(name)) {
        process.stderr.write(`error: line ${lineNum + 1}: invalid policy name ${name}\n`);
        process.exit(2);
      }

      if (policies.has(name)) {
        process.stderr.write(`error: line ${lineNum + 1}: policy ${name} is declared twice\n`);
        process.exit(2);
      }

      if (!isValidInteger(capacityStr, 1)) {
        process.stderr.write(`error: line ${lineNum + 1}: capacity must be an integer of at least 1\n`);
        process.exit(2);
      }

      if (!isValidInteger(refillStr, 0)) {
        process.stderr.write(`error: line ${lineNum + 1}: refill must be an integer of at least 0\n`);
        process.exit(2);
      }

      if (!isValidInteger(perStr, 1)) {
        process.stderr.write(`error: line ${lineNum + 1}: per must be an integer of at least 1\n`);
        process.exit(2);
      }

      const capacity = parseInt(capacityStr, 10);
      const refill = parseInt(refillStr, 10);
      const per = parseInt(perStr, 10);

      policies.set(name, {
        type: 'bucket',
        instance: new TokenBucket(capacity, refill, per)
      });

    } else if (directive === 'window') {
      if (firstEventLine !== -1) {
        process.stderr.write(`error: line ${lineNum + 1}: declarations must come before the first event\n`);
        process.exit(2);
      }

      if (tokens.length !== 4) {
        process.stderr.write(`error: line ${lineNum + 1}: expected window <name> <limit> <span>\n`);
        process.exit(2);
      }

      const [, name, limitStr, spanStr] = tokens;

      if (!isValidIdentifier(name)) {
        process.stderr.write(`error: line ${lineNum + 1}: invalid policy name ${name}\n`);
        process.exit(2);
      }

      if (policies.has(name)) {
        process.stderr.write(`error: line ${lineNum + 1}: policy ${name} is declared twice\n`);
        process.exit(2);
      }

      if (!isValidInteger(limitStr, 0)) {
        process.stderr.write(`error: line ${lineNum + 1}: limit must be an integer of at least 0\n`);
        process.exit(2);
      }

      if (!isValidInteger(spanStr, 1)) {
        process.stderr.write(`error: line ${lineNum + 1}: span must be an integer of at least 1\n`);
        process.exit(2);
      }

      const limit = parseInt(limitStr, 10);
      const span = parseInt(spanStr, 10);

      policies.set(name, {
        type: 'window',
        instance: new SlidingWindow(limit, span)
      });

    } else if (directive === 'route') {
      if (firstEventLine !== -1) {
        process.stderr.write(`error: line ${lineNum + 1}: declarations must come before the first event\n`);
        process.exit(2);
      }

      if (tokens.length < 3) {
        process.stderr.write(`error: line ${lineNum + 1}: expected route <prefix> <policy>...\n`);
        process.exit(2);
      }

      const prefix = tokens[1];
      const policyNames = tokens.slice(2);

      if (!isValidIdentifier(prefix)) {
        process.stderr.write(`error: line ${lineNum + 1}: invalid route prefix ${prefix}\n`);
        process.exit(2);
      }

      if (routes.has(prefix)) {
        process.stderr.write(`error: line ${lineNum + 1}: prefix ${prefix} is routed twice\n`);
        process.exit(2);
      }

      for (const policyName of policyNames) {
        if (!policies.has(policyName)) {
          process.stderr.write(`error: line ${lineNum + 1}: unknown policy ${policyName}\n`);
          process.exit(2);
        }
      }

      routes.set(prefix, policyNames);

    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        process.stderr.write(`error: line ${lineNum + 1}: expected event <tick> <key>\n`);
        process.exit(2);
      }

      const [, tickStr, key] = tokens;

      if (!isValidInteger(tickStr)) {
        process.stderr.write(`error: line ${lineNum + 1}: tick must be an integer of at least 0\n`);
        process.exit(2);
      }

      if (!isValidIdentifier(key)) {
        process.stderr.write(`error: line ${lineNum + 1}: invalid key ${key}\n`);
        process.exit(2);
      }

      const tick = parseInt(tickStr, 10);

      if (firstEventLine === -1) {
        firstEventLine = lineNum + 1;
        lastTick = tick;
      } else if (tick < lastTick) {
        process.stderr.write(`error: line ${lineNum + 1}: tick ${tick} is before tick ${lastTick}\n`);
        process.exit(2);
      }

      events.push({ tick, key });
      lastTick = tick;

    } else {
      process.stderr.write(`error: line ${lineNum + 1}: unknown directive ${directive}\n`);
      process.exit(2);
    }
  }

  // Process events
  const results = [];
  const keyStats = new Map();

  for (const event of events) {
    const { tick, key } = event;

    // Find the longest matching route
    let matchingRoute = null;
    let longestPrefix = '';
    for (const [prefix, policyNames] of routes) {
      if (key.startsWith(prefix) && prefix.length > longestPrefix.length) {
        matchingRoute = policyNames;
        longestPrefix = prefix;
      }
    }

    // Track this key
    if (!keyStats.has(key)) {
      keyStats.set(key, { allowed: 0, denied: 0 });
    }

    if (!matchingRoute) {
      // No route matches, allow
      results.push({ tick, key, allowed: true });
      keyStats.get(key).allowed++;
    } else {
      // Advance all policies
      for (const policyName of matchingRoute) {
        const policy = policies.get(policyName);
        policy.instance.advance(key, tick);
      }

      // Check if all policies allow
      let allowedByAll = true;
      let deniedBy = null;
      for (const policyName of matchingRoute) {
        const policy = policies.get(policyName);
        if (!policy.instance.allow(key)) {
          allowedByAll = false;
          deniedBy = policyName;
          break;
        }
      }

      if (allowedByAll) {
        // Record in all policies
        for (const policyName of matchingRoute) {
          const policy = policies.get(policyName);
          policy.instance.record(key, tick);
        }
        results.push({ tick, key, allowed: true });
        keyStats.get(key).allowed++;
      } else {
        results.push({ tick, key, allowed: false, deniedBy });
        keyStats.get(key).denied++;
      }
    }
  }

  // Output
  if (mode === 'replay') {
    for (const result of results) {
      if (result.allowed) {
        console.log(`${result.tick} ${result.key} allow`);
      } else {
        console.log(`${result.tick} ${result.key} deny ${result.deniedBy}`);
      }
    }
  } else {
    // summary
    const sortedKeys = Array.from(keyStats.keys()).sort();
    for (const key of sortedKeys) {
      const stats = keyStats.get(key);
      console.log(`${key} allowed=${stats.allowed} denied=${stats.denied}`);
    }
    const totalAllowed = Array.from(keyStats.values()).reduce((sum, s) => sum + s.allowed, 0);
    const totalDenied = Array.from(keyStats.values()).reduce((sum, s) => sum + s.denied, 0);
    console.log(`total allowed=${totalAllowed} denied=${totalDenied}`);
  }
}

main();
