      routes.set(prefix, policyNames);

    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        process.stderr.write(`error: line ${lineNum + 1}: expected event <tick> <key>\n`);
        process.exit(2);
      }

      const [, tickStr, key] = tokens;

      if (!isValidInteger(tickStr)) {
        process.stderr.write(`error: line ${lineNum + 1}: tick must be an integer of at least 0\n`);
        process.exit(2);
      }

      if (!isValidIdentifier(key)) {
        process.stderr.write(`error: line ${lineNum + 1}: invalid key ${key}\n`);
        process.exit(2);
      }

      const tick = parseInt(tickStr, 10);

      if (firstEventLine === -1) {
        firstEventLine = lineNum + 1;
        lastTick = tick;
      } else if (tick < lastTick) {
        process.stderr.write(`error: line ${lineNum + 1}: tick ${tick} is before tick ${lastTick}\n`);
        process.exit(2);
      }

      events.push({ tick, key });
      lastTick = tick;

    } else {
      process.stderr.write(`error: line ${lineNum + 1}: unknown directive ${directive}\n`);
      process.exit(2);
    }
  }

  // Process events
  const results = [];
  const keyStats = new Map();

  for (const event of events) {
    const { tick, key } = event;

    // Find the longest matching route
    let matchingRoute = null;
    let longestPrefix = '';
    for (const [prefix, policyNames] of routes) {
      if (key.startsWith(prefix) && prefix.length > longestPrefix.length) {
        matchingRoute = policyNames;
        longestPrefix = prefix;
      }
    }

    // Track this key
    if (!keyStats.has(key)) {
      keyStats.set(key, { allowed: 0, denied: 0 });
    }

    if (!matchingRoute) {
      // No route matches, allow
      results.push({ tick, key, allowed: true });
      keyStats.get(key).allowed++;
    } else {
      // Advance all policies
      for (const policyName of matchingRoute) {
        const policy = policies.get(policyName);
        policy.instance.advance(key, tick);
      }

      // Check if all policies allow
      let allowedByAll = true;
      let deniedBy = null;
      for (const policyName of matchingRoute) {
        const policy = policies.get(policyName);
        if (!policy.instance.allow(key)) {
          allowedByAll = false;
          deniedBy = policyName;
          break;
        }
      }

      if (allowedByAll) {
        // Record in all policies
        for (const policyName of matchingRoute) {
          const policy = policies.get(policyName);
          policy.instance.record(key, tick);
        }
        results.push({ tick, key, allowed: true });
        keyStats.get(key).allowed++;
      } else {
        results.push({ tick, key, allowed: false, deniedBy });
        keyStats.get(key).denied++;
      }
    }
  }

  // Output
  if (mode === 'replay') {
    for (const result of results) {
      if (result.allowed) {
        console.log(`${result.tick} ${result.key} allow`);
      } else {
        console.log(`${result.tick} ${result.key} deny ${result.deniedBy}`);
      }
    }
  } else {
    // summary
    const sortedKeys = Array.from(keyStats.keys()).sort();
    for (const key of sortedKeys) {
      const stats = keyStats.get(key);
      console.log(`${key} allowed=${stats.allowed} denied=${stats.denied}`);
    }
    const totalAllowed = Array.from(keyStats.values()).reduce((sum, s) => sum + s.allowed, 0);
    const totalDenied = Array.from(keyStats.values()).reduce((sum, s) => sum + s.denied, 0);
    console.log(`total allowed=${totalAllowed} denied=${totalDenied}`);
  }
}

