class TokenBucket {
  // Tokens are held exactly, as an integer numerator over `per`, so that
  // fractional refills accumulate without any rounding.
  constructor(capacity, refill, per) {
    this.capacity = BigInt(capacity);
    this.refill = BigInt(refill);
    this.per = BigInt(per);
    this.cap = this.capacity * this.per;
    this.state = new Map(); // key -> {tokens: bigint numerator, lastTick: bigint}
  }

  advance(key, tick) {
    const t = BigInt(tick);
    if (!this.state.has(key)) {
      this.state.set(key, { tokens: this.cap, lastTick: t });
    } else {
      const state = this.state.get(key);
      const ticksPassed = t - state.lastTick;
      const added = this.refill * ticksPassed;
      const next = state.tokens + added;
      state.tokens = next > this.cap ? this.cap : next;
      state.lastTick = t;
    }
  }

  allow(key) {
    return this.state.get(key).tokens >= this.per;
  }

  record(key, tick) {
    this.state.get(key).tokens -= this.per;
  }
}
